package vn.autosort;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.security.crypto.argon2.Argon2PasswordEncoder;

class CompatibilityTest {
  @Test
  void verifiesExistingPythonArgon2idWithoutResettingPassword() {
    // Generated by pwdlib/argon2-cffi using a test-only password; not an account credential.
    String hash =
        "$argon2id$v=19$m=65536,t=3,p=4$qZIY41zIV5wIj2UOuTXk4Q$TBLArPJT8/7+v2M6iZM9oqWGU6WXtCv/7ZfxXtQGfUA";
    var encoder = Argon2PasswordEncoder.defaultsForSpringSecurity_v5_8();
    assertTrue(encoder.matches("Python-compatibility-test-only!", hash));
    assertFalse(encoder.matches("wrong", hash));
  }

  @Test
  void cloudRejectsInsecureOriginsAndCookiesWithoutPrintingSecrets() {
    var env =
        new MockEnvironment()
            .withProperty("DEVICE_API_KEY", "k".repeat(40))
            .withProperty("RENDER", "true")
            .withProperty("RENDER_EXTERNAL_URL", "https://example.onrender.com")
            .withProperty("COOKIE_SECURE", "false");
    assertThrows(IllegalStateException.class, () -> new Settings(env));
    env.withProperty("COOKIE_SECURE", "true");
    var settings = new Settings(env);
    assertTrue(settings.secure);
    assertEquals("https://example.onrender.com", settings.origins.getFirst());
    env.withProperty("ALLOWED_ORIGINS", "*");
    assertThrows(IllegalStateException.class, () -> new Settings(env));
  }
}
